    <option>Heap property</option>
    <option>Both</option>
  </select>
</label>
<span style="font-size:11px;color:#555;line-height:1.4">Click any tree circle or array cell to select it — the match lights up in <b style="color:#F28C28">both</b> views, with its <b style="color:#2f6fb5">parent</b> and <b style="color:#4e9c58">children</b>.</span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
(function () {
  var C = document.getElementById('container');
  var draw = SVG().addTo(C).size('100%', '100%');
  draw.viewbox(0, 0, 1200, 500);

  var SERIF = "'Times New Roman', Times, serif";
  var SANS = "sans-serif";

  var A = [null, 16, 14, 10, 8, 7, 9, 3, 2, 4, 1];
  var N = 10;

  var GRAY = '#D9D9D9', SEL = '#F28C28', PAR = '#7FB2E5', CHI = '#9FD6A5';
  var SELS = '#c96a12', PARS = '#2f6fb5', CHIS = '#4e9c58';

  // ---------- tree geometry ----------
  var R = 26;
  var POS = {
    1: [340, 62],
    2: [200, 158], 3: [480, 158],
    4: [130, 254], 5: [270, 254], 6: [410, 254], 7: [550, 254],
    8: [95, 350], 9: [165, 350], 10: [235, 350]
  };

  // ---------- array geometry ----------
  var X0 = 690, CW = 46, CH = 50, ATOP = 215, ABOT = ATOP + CH;
  function cx(i) { return X0 + CW * (i - 0.5); }

  var gEdges = draw.group(), gArcs = draw.group(), gNodes = draw.group(),
      gCells = draw.group(), gLabels = draw.group(), gBadges = draw.group(),
      gPanel = draw.group();

  function halo(t) {
    t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3.2, 'stroke-linejoin': 'round' });
    return t;
  }

  // ---------- tree edges ----------
  var edges = {};
  for (var c = 2; c <= N; c++) {
    var p = c >> 1;
    edges[c] = gEdges.line(POS[p][0], POS[p][1], POS[c][0], POS[c][1])
      .stroke({ color: '#000', width: 1.6, linecap: 'round' });
  }

  // ---------- array arcs ----------
  function arcGeom(i, ch) {
    var x1 = cx(i), x2 = cx(ch), above = (i <= 3);
    var y = above ? ATOP : ABOT;
    var span = Math.abs(x2 - x1), h = 18 + span * 0.18;
    return { x1: x1, x2: x2, y: y, h: h, above: above, cyq: above ? y - 2 * h : y + 2 * h };
  }
  var arcs = {};
  for (var c2 = 2; c2 <= N; c2++) {
    var pp = c2 >> 1, g = arcGeom(pp, c2);
    arcs[c2] = gArcs.path('M' + g.x1 + ',' + g.y + ' Q' + ((g.x1 + g.x2) / 2) + ',' + g.cyq + ' ' + g.x2 + ',' + g.y)
      .fill('none').stroke({ color: '#000', width: 1.2 });
  }

  // ---------- tree nodes ----------
  var nodes = {};
  function nodeTip(i) {
    var p = i >> 1, l = 2 * i, r = 2 * i + 1;
    return 'index ' + i + ' · A[' + i + '] = ' + A[i] +
      ' · parent ' + (p >= 1 ? p : 'none') +
      ' · children ' + (l <= N ? l : '–') + ', ' + (r <= N ? r : '–');
  }
  function nodePopup(i) {
    var p = i >> 1, l = 2 * i, r = 2 * i + 1;
    var s = 'A[' + i + '] = ' + A[i] + '. Its parent index is ⌊' + i + '/2⌋ = ' + p +
      (p >= 1 ? ' which holds ' + A[p] + '.' : ', which is outside the array — so this is the root.');
    s += ' Its children are at 2i = ' + l + (l <= N ? ' (value ' + A[l] + ')' : ' — beyond heap-size 10') +
      ' and 2i+1 = ' + r + (r <= N ? ' (value ' + A[r] + ')' : ' — beyond heap-size 10') + '.';
    s += ' None of these links are stored anywhere: they are recomputed from the index alone.';
    showPopup('Node / cell ' + i, s);
  }

  for (var i = 1; i <= N; i++) {
    (function (i) {
      var x = POS[i][0], y = POS[i][1];
      var gg = gNodes.group();
      var circ = gg.circle(2 * R).center(x, y).fill(GRAY).stroke({ color: '#000', width: 1.7 });
      circ.css({ transition: 'fill .18s' });
      var tv = gg.text(String(A[i])).font({ family: SERIF, size: 21, anchor: 'middle' }).fill('#000');
      tv.center(x, y);
      gg.css('cursor', 'pointer');
      gg.on('mousemove', function (e) { showTooltip(nodeTip(i), e); });
      gg.on('mouseleave', hideTooltip);
      gg.on('click', function () { selectIndex(i); nodePopup(i); });

      // index numeral outside the circle, on the side away from the incoming edge
      var lx, ly = y - R - 7, anch = 'middle';
      if (i === 1) { lx = x; }
      else if (i % 2 === 0) { lx = x - R - 5; }
      else { lx = x + R + 5; }
      halo(gLabels.text(String(i)).font({ family: SERIF, size: 17, anchor: anch }).fill('#000')
        .amove(lx, ly - 10));
      nodes[i] = { g: gg, circle: circ, text: tv };
    })(i);
  }

  // ---------- array cells ----------
  var cells = {};
  for (var k = 1; k <= N; k++) {
    (function (k) {
      var gx = X0 + CW * (k - 1);
      var gg = gCells.group();
      var rct = gg.rect(CW, CH).move(gx, ATOP).fill(GRAY).stroke({ color: '#000', width: 1.7 });
      rct.css({ transition: 'fill .18s' });
      var tv = gg.text(String(A[k])).font({ family: SERIF, size: 21, anchor: 'middle' }).fill('#000');
      tv.center(gx + CW / 2, ATOP + CH / 2);
      gg.css('cursor', 'pointer');
      gg.on('mousemove', function (e) { showTooltip(nodeTip(k), e); });
      gg.on('mouseleave', hideTooltip);
      gg.on('click', function () { selectIndex(k); nodePopup(k); });
      halo(gLabels.text(String(k)).font({ family: SERIF, size: 17, anchor: 'middle' }).fill('#000')
        .amove(cx(k), 132));
      cells[k] = { g: gg, rect: rct, text: tv };
    })(k);
  }

  // ---------- comparison badges ----------
  var badges = { tree: {}, arr: {} };
  for (var c3 = 2; c3 <= N; c3++) {
    (function (c) {
      var p = c >> 1;
      var txt = A[p] + ' \u2265 ' + A[c];
      var mx = (POS[p][0] + POS[c][0]) / 2, my = (POS[p][1] + POS[c][1]) / 2;
      var t1 = gBadges.text(txt).font({ family: SANS, size: 11.5, anchor: 'middle' }).fill('#1d6b2c');
      halo(t1); t1.center(mx, my);
      var g = arcGeom(p, c);
      var ax = (g.x1 + g.x2) / 2, ay = g.above ? g.y - g.h - 5 : g.y + g.h + 6;
      var t2 = gBadges.text(txt).font({ family: SANS, size: 10, anchor: 'middle' }).fill('#1d6b2c');
      halo(t2); t2.center(ax, ay);
      badges.tree[c] = t1; badges.arr[c] = t2;
    })(c3);
  }

  // ---------- captions, annotation, legend, readout ----------
  gPanel.text('(a)').font({ family: SERIF, size: 23, anchor: 'middle' }).fill('#000').amove(340, 462);
  gPanel.text('(b)').font({ family: SERIF, size: 23, anchor: 'middle' }).fill('#000').amove(920, 462);

  gPanel.text('A.length = A.heap-size = 10')
    .font({ family: SERIF, size: 15, anchor: 'start', style: 'italic' }).fill('#333').amove(690, 334);

  // legend under the tree
  var legRows = [[SEL, 'i  — selected'], [PAR, '\u230Ai/2\u230B — parent'], [CHI, '2i, 2i+1 — children']];
  for (var L = 0; L < legRows.length; L++) {
    gPanel.rect(14, 14).move(72, 396 + L * 22).fill(legRows[L][0]).stroke({ color: '#000', width: 1 });
    gPanel.text(legRows[L][1]).font({ family: SANS, size: 12.5, anchor: 'start' }).fill('#222')
      .amove(94, 393 + L * 22);
  }

  gPanel.rect(460, 98).move(690, 350).fill('#fbfbfc').stroke({ color: '#c9ced4', width: 1 }).radius(4);
  var RO = [];
  for (var q = 0; q < 4; q++) {
    RO.push(gPanel.text('').font({ family: SANS, size: 13.5, anchor: 'start' }).fill('#222')
      .amove(702, 356 + q * 22));
  }

  // ---------- state & render ----------
  var state = { i: 1, mode: 'Structural links' };

  function render() {
    var i = state.i, p = i >> 1, l = 2 * i, r = 2 * i + 1;
    var role = {};
    if (p >= 1) role[p] = 'par';
    if (l <= N) role[l] = 'chi';
    if (r <= N) role[r] = 'chi';
    role[i] = 'sel';

    for (var k = 1; k <= N; k++) {
      var f = role[k] === 'sel' ? SEL : role[k] === 'par' ? PAR : role[k] === 'chi' ? CHI : GRAY;
      nodes[k].circle.fill(f);
      cells[k].rect.fill(f);
    }

    var dim = (state.mode === 'Heap property');
    for (var c = 2; c <= N; c++) {
      var pp = c >> 1, rl = 'none';
      if (c === i && pp >= 1) rl = 'par';
      else if (pp === i) rl = 'chi';
      var col = rl === 'par' ? PARS : rl === 'chi' ? CHIS : '#000';
      var op = rl === 'none' ? (dim ? 0.18 : 1) : 1;
      edges[c].stroke({ color: col, width: rl === 'none' ? 1.6 : 3.6 }).opacity(op);
      arcs[c].stroke({ color: col, width: rl === 'none' ? 1.2 : 3 }).opacity(op);
    }

    gBadges.css('display', state.mode === 'Structural links' ? 'none' : '');

    // readout
    RO[0].text('i = ' + i + '      A[i] = ' + A[i]).fill(SELS);
    if (p >= 1) RO[1].text('PARENT(i) = \u230Ai/2\u230B = ' + p + '   \u2192   A[' + p + '] = ' + A[p]).fill(PARS);
    else RO[1].text('PARENT(i) = \u230A1/2\u230B = 0   \u2192   none (root)').fill('#9aa0a6');
    if (l <= N) RO[2].text('LEFT(i) = 2i = ' + l + '   \u2192   A[' + l + '] = ' + A[l]).fill(CHIS);
    else RO[2].text('LEFT(i) = 2i = ' + l + '   \u2192   none ( > heap-size 10 )').fill('#9aa0a6');
    if (r <= N) RO[3].text('RIGHT(i) = 2i+1 = ' + r + '   \u2192   A[' + r + '] = ' + A[r]).fill(CHIS);
    else RO[3].text('RIGHT(i) = 2i+1 = ' + r + '   \u2192   none ( > heap-size 10 )').fill('#9aa0a6');
  }

  // ---------- public control handlers ----------
  window.update_indexSlider = function (v) { state.i = Math.max(1, Math.min(N, v | 0)); render(); };
  window.toggle_overlayMode = function (m) { state.mode = m; render(); };

  function selectIndex(i) {
    state.i = i;
    var s = document.getElementById('indexSliderInput');
    var o = document.getElementById('indexSliderVal');
    if (s) s.value = i;
    if (o) o.value = i;
    render();
  }
  window.selectHeapIndex = selectIndex;

  // ---------- demo steps ----------
  var steps = [
    { title: 'Two pictures, one heap', narration: 'On the left a binary tree, on the right a flat array — but the values read off level by level, left to right, are identical: 16, 14, 10, 8, 7, 9, 3, 2, 4, 1. The arcs on the array show the tree edges hiding inside the row.', state: { indexSlider: 1, overlayMode: 'Structural links' } },
    { title: 'The root and its children', narration: 'With i = 1, the children are at 2i = 2 and 2i + 1 = 3 — cells 14 and 10, exactly the root\u2019s two tree children. There is no parent, since \u230A1/2\u230B = 0 falls outside the array.', state: { indexSlider: 1, overlayMode: 'Structural links' } },
    { title: 'Climbing up: parent = \u230Ai/2\u230B', narration: 'At i = 5 the parent index is \u230A5/2\u230B = 2, and indeed the node holding 7 hangs below the node holding 14. Both 4 and 5 map back to the same parent 2 — integer division folds two children into one parent.', state: { indexSlider: 5, overlayMode: 'Structural links' } },
    { title: 'Where the tree runs out', narration: 'At i = 5 the children would be 10 and 11, but the heap size is 10, so node 5 has only a left child. Sweep further to i = 6 or beyond and both child indices exceed the array — those are the leaves.', state: { indexSlider: 6, overlayMode: 'Structural links' } },
    { title: 'The max-heap property', narration: 'Switch the overlay to value order: every edge now carries A[parent] \u2265 A[child]. 16 \u2265 14, 14 \u2265 8, 8 \u2265 4 — the largest element sits at the root, but siblings like 7 and 9 are in no particular order.', state: { indexSlider: 4, overlayMode: 'Heap property' } },
    { title: 'Layout and order together', narration: 'Showing both overlays at once separates the two ideas: index arithmetic decides who is whose child, and the heap property constrains only the values along those parent-child links — never across the array left to right.', state: { indexSlider: 2, overlayMode: 'Both' } }
  ];
  var cur = 0;

  function setStep(k) {
    cur = (k + steps.length) % steps.length;
    var st = steps[cur];
    var s = document.getElementById('indexSliderInput');
    var o = document.getElementById('indexSliderVal');
    if (s) s.value = st.state.indexSlider;
    if (o) o.value = st.state.indexSlider;
    var sel = document.getElementById('overlayModeInput');
    if (sel) sel.value = st.state.overlayMode;
    window.update_indexSlider(st.state.indexSlider);
    window.toggle_overlayMode(st.state.overlayMode);
    var nar = document.getElementById('demoNarration');
    if (nar) nar.innerHTML = '<b>' + st.title + '</b><br>' + st.narration;
    var lab = document.getElementById('stepLabel');
    if (lab) lab.textContent = 'Step ' + (cur + 1) + ' / ' + steps.length;
  }
  window.nextStep = function () { setStep(cur + 1); };
  window.prevStep = function () { setStep(cur - 1); };

  setStep(0);
  window.__markRendered();
})();
// @FIGURE_CODE_END

