  var VW = 1200, VH = 450;
  draw.viewbox(0, 0, VW, VH);

  var SERIF = "'Times New Roman', Times, serif";
  var SANS = "sans-serif";

  var A = [null, 16, 14, 10, 8, 7, 9, 3, 2, 4, 1];
  var N = 10;

  var GRAY = '#D9D9D9';
  var SEL = '#F5871F', PAR = '#7EB0E8', CHI = '#8FCF9B';
  var SELD = '#B05E08', PARD = '#245E9E', CHID = '#2F7D3A';

  // ---------- tree geometry ----------
  var R = 34;
  var POS = {
    1: [344, 65],
    2: [198, 159], 3: [480, 159],
    4: [104, 254], 5: [292, 254], 6: [389, 254], 7: [577, 254],
    8: [49, 352], 9: [146, 352], 10: [241, 352]
  };

  // ---------- array geometry ----------
  var X0 = 702, CW = 48, CH = 50, ATOP = 232, ABOT = ATOP + CH;
  function cx(i) { return X0 + CW * (i - 0.5); }

  var gEdges = draw.group(), gArcs = draw.group(), gNodes = draw.group(),
      gCells = draw.group(), gLabels = draw.group(), gBadges = draw.group(),
      gReadout = draw.group(), gCaps = draw.group();

  function halo(t, w) {
    t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': (w || 3.4), 'stroke-linejoin': 'round' });
    return t;
  }

  // ---------- tree edges ----------
  var edges = {};
  for (var c = 2; c <= N; c++) {
    var p = c >> 1;
    edges[c] = gEdges.line(POS[p][0], POS[p][1], POS[c][0], POS[c][1])
      .stroke({ color: '#000', width: 1.8, linecap: 'round' });
  }

  // ---------- array arcs ----------
  function arcGeom(i, ch) {
    var x1 = cx(i), x2 = cx(ch), above = (i <= 3);
    var y = above ? ATOP : ABOT;
    var span = Math.abs(x2 - x1);
    var h = Math.min(42, 12 + span * 0.13);
    return { x1: x1, x2: x2, y: y, h: h, above: above, cy: above ? y - 2 * h : y + 2 * h };
  }
  var arcs = {};
