    s += ' Its children are at 2i = ' + l + (l <= N ? ' (value ' + A[l] + ')' : ' — past heap-size 10') +
      ' and 2i+1 = ' + r + (r <= N ? ' (value ' + A[r] + ')' : ' — past heap-size 10') + '.';
    s += ' None of these links are stored: they are recomputed from the index alone.';
    showPopup('Index ' + i, s);
  }

  // ---------- tree nodes ----------
  var nodes = {};
  for (var i = 1; i <= N; i++) {
    (function (i) {
      var x = POS[i][0], y = POS[i][1];
      var gg = gNodes.group();
      var circ = gg.circle(2 * R).center(x, y).fill(GRAY).stroke({ color: '#000', width: 1.8 });
      circ.css({ transition: 'fill .18s' });
      var tv = gg.text(String(A[i])).font({ family: SERIF, size: 27, anchor: 'middle' }).fill('#000');
      tv.center(x, y);
      gg.css('cursor', 'pointer');
      gg.on('mousemove', function (e) { showTooltip(nodeTip(i), e); });
      gg.on('mouseleave', hideTooltip);
      gg.on('click', function () { selectIndex(i); nodePopup(i); });

      // index numeral outside the circle, offset away from the incoming edge
