      halo(gLabels.text(String(i)).font({ family: SERIF, size: 20, anchor: 'middle' }).fill('#000')
        .center(x + off, y - R - 14));
      nodes[i] = { circle: circ, text: tv };
    })(i);
  }

  // ---------- array cells ----------
  var cells = {};
  for (var k = 1; k <= N; k++) {
    (function (k) {
      var gx = X0 + CW * (k - 1);
      var gg = gCells.group();
      var rct = gg.rect(CW, CH).move(gx, ATOP).fill(GRAY).stroke({ color: '#000', width: 1.8 });
      rct.css({ transition: 'fill .18s' });
      var tv = gg.text(String(A[k])).font({ family: SERIF, size: 27, anchor: 'middle' }).fill('#000');
      tv.center(gx + CW / 2, ATOP + CH / 2);
      gg.css('cursor', 'pointer');
      gg.on('mousemove', function (e) { showTooltip(nodeTip(k), e); });
      gg.on('mouseleave', hideTooltip);
      gg.on('click', function () { selectIndex(k); nodePopup(k); });
