      var perp = (POS[c][0] > POS[p][0]) ? 20 : -20;
      var t1 = gBadges.text(txt).font({ family: SANS, size: 18, anchor: 'middle' }).fill(CHID);
      halo(t1, 4); t1.center(mx + perp, my - 6);
      var g = arcGeom(p, c);
