    RO.push(gReadout.text('').font({ family: SANS, size: 21, anchor: 'start' }).fill('#222')
      .amove(716, 22 + q * 29));
  }
  var ROsize = gReadout.text('A.length = A.heap-size = 10')
    .font({ family: SERIF, size: 20, anchor: 'start', style: 'italic' }).fill('#444').amove(716, 138);
  gReadout.css('display', 'none');

