    { title: 'The max-heap property', narration: 'Now the value order: every edge carries A[parent] \u2265 A[child]. 16 \u2265 14, 14 \u2265 8, 8 \u2265 4. The largest element must sit at the root, yet siblings such as 7 and 9 are in no particular order.', state: { i: 4, mode: 'Heap property' } },
