  ];
  var cur = 0;

  function setStep(k) {
    cur = (k + steps.length) % steps.length;
    var st = steps[cur];
    syncInputs(st.state.i, st.state.mode);
    apply(st.state.i, st.state.mode, cur !== 0);
    var nar = document.getElementById('demoNarration');
    if (nar) nar.innerHTML = '<b>' + st.title + '</b><br>' + st.narration;
    var lab = document.getElementById('stepLabel');
    if (lab) lab.textContent = 'Step ' + (cur + 1) + ' / ' + steps.length;
  }
  window.nextStep = function () { setStep(cur + 1); };
  window.prevStep = function () { setStep(cur - 1); };

  setStep(0);
  window.__markRendered();
})();
