    <option>Heap property</option>
    <option>Both</option>
  </select>
</label>
<button onclick="trigger_clearSel()">Reset to plain figure</button>
<span style="font-size:12px;line-height:1.6;color:#222">
  <span style="display:inline-block;width:11px;height:11px;background:#F5871F;border:1px solid #000;vertical-align:-1px"></span>
  &nbsp;i — selected<br>
  <span style="display:inline-block;width:11px;height:11px;background:#7EB0E8;border:1px solid #000;vertical-align:-1px"></span>
  &nbsp;⌊i/2⌋ — parent<br>
  <span style="display:inline-block;width:11px;height:11px;background:#8FCF9B;border:1px solid #000;vertical-align:-1px"></span>
  &nbsp;2i, 2i+1 — children
</span>
<span style="font-size:12px;color:#555;line-height:1.5">Click any tree circle or array cell: the same item lights up in <b>both</b> views, with its parent and children. Hover an edge or arc to see its heap-property test.</span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
(function () {
  var C = document.getElementById('container');
  var draw = SVG().addTo(C).size('100%', '100%');
  var VW = 1120, VH = 424;
  draw.viewbox(0, 0, VW, VH);

  var SERIF = "'Times New Roman', Times, serif";
  var SANS = "sans-serif";

  var A = [null, 16, 14, 10, 8, 7, 9, 3, 2, 4, 1];
  var N = 10;

  var GRAY = '#D9D9D9';
  var SEL = '#F5871F', PAR = '#7EB0E8', CHI = '#8FCF9B';
  var SELD = '#B05E08', PARD = '#245E9E', CHID = '#2F7D3A';

  // ---------- tree geometry ----------
  var R = 38;
  var POS = {
    1: [309, 62],
    2: [177, 152], 3: [441, 152],
    4: [90, 242], 5: [264, 242], 6: [356, 242], 7: [527, 242],
    8: [44, 332], 9: [137, 332], 10: [222, 332]
  };

  // ---------- array geometry ----------
  var X0 = 600, CW = 50, CH = 54, ATOP = 228, ABOT = ATOP + CH;
  function cx(i) { return X0 + CW * (i - 0.5); }

  var gEdges = draw.group(), gArcs = draw.group(), gHit = draw.group(),
      gNodes = draw.group(), gCells = draw.group(), gLabels = draw.group(),
      gBadges = draw.group(), gReadout = draw.group(), gCaps = draw.group();

  function halo(t, w) {
    t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': (w || 3.6), 'stroke-linejoin': 'round' });
    return t;
  }

  function linkTip(p, c) {
    return 'link ' + p + ' \u2192 ' + c + '   (parent \u230A' + c + '/2\u230B = ' + p + ')' +
      '   \u00b7   A[' + p + '] = ' + A[p] + ' \u2265 A[' + c + '] = ' + A[c];
  }

  // ---------- tree edges ----------
  var edges = {};
  for (var c = 2; c <= N; c++) {
    (function (c) {
      var p = c >> 1;
      edges[c] = gEdges.line(POS[p][0], POS[p][1], POS[c][0], POS[c][1])
        .stroke({ color: '#000', width: 1.8, linecap: 'round' });
      var hit = gHit.line(POS[p][0], POS[p][1], POS[c][0], POS[c][1])
        .stroke({ color: '#000', width: 16, opacity: 0, linecap: 'round' });
      hit.css('cursor', 'pointer');
      hit.on('mousemove', function (e) { showTooltip(linkTip(p, c), e); });
      hit.on('mouseleave', hideTooltip);
      hit.on('click', function () { selectIndex(c); });
    })(c);
  }

  // ---------- array arcs ----------
  function arcGeom(i, ch) {
    var x1 = cx(i), x2 = cx(ch), above = (i <= 3);
    var y = above ? ATOP : ABOT;
    var span = Math.abs(x2 - x1);
    var h = above ? Math.min(38, 10 + span * 0.14) : Math.min(46, 8 + span * 0.15);
    return { x1: x1, x2: x2, y: y, h: h, above: above, cy: above ? y - 2 * h : y + 2 * h };
  }
  function arcPath(g) {
    return 'M' + g.x1 + ',' + g.y + ' Q' + ((g.x1 + g.x2) / 2) + ',' + g.cy + ' ' + g.x2 + ',' + g.y;
  }
  var arcs = {};
  for (var c2 = 2; c2 <= N; c2++) {
    (function (c) {
      var p = c >> 1, g = arcGeom(p, c), d = arcPath(g);
      arcs[c] = gArcs.path(d).fill('none').stroke({ color: '#000', width: 1.3 });
      var hit = gHit.path(d).fill('none').stroke({ color: '#000', width: 14, opacity: 0 });
      hit.css('cursor', 'pointer');
      hit.on('mousemove', function (e) { showTooltip(linkTip(p, c), e); });
      hit.on('mouseleave', hideTooltip);
      hit.on('click', function () { selectIndex(c); });
    })(c2);
  }

  // ---------- hover / click text ----------
  function nodeTip(i) {
    var p = i >> 1, l = 2 * i, r = 2 * i + 1;
    return 'index ' + i + ' \u00b7 A[' + i + '] = ' + A[i] +
      ' \u00b7 parent ' + (p >= 1 ? p : 'none') +
      ' \u00b7 children ' + (l <= N ? l : '\u2013') + ', ' + (r <= N ? r : '\u2013');
  }
  function nodePopup(i) {
    var p = i >> 1, l = 2 * i, r = 2 * i + 1;
    var s = 'A[' + i + '] = ' + A[i] + '. Its parent index is \u230A' + i + '/2\u230B = ' + p +
      (p >= 1 ? ', which holds ' + A[p] + '.' : ', which falls outside the array \u2014 so this is the root.');
    s += ' Its children are at 2i = ' + l + (l <= N ? ' (value ' + A[l] + ')' : ' \u2014 past heap-size 10') +
      ' and 2i+1 = ' + r + (r <= N ? ' (value ' + A[r] + ')' : ' \u2014 past heap-size 10') + '.';
    s += ' None of these links are stored: they are recomputed from the index alone.';
    showPopup('Index ' + i, s);
  }

  // ---------- tree nodes ----------
  var nodes = {};
  for (var i = 1; i <= N; i++) {
    (function (i) {
      var x = POS[i][0], y = POS[i][1];
      var gg = gNodes.group();
      var circ = gg.circle(2 * R).center(x, y).fill(GRAY).stroke({ color: '#000', width: 1.8 });
      circ.css({ transition: 'fill .18s' });
      var tv = gg.text(String(A[i])).font({ family: SERIF, size: 28, anchor: 'middle' }).fill('#000');
      tv.center(x, y);
      gg.css('cursor', 'pointer');
      gg.on('mousemove', function (e) { showTooltip(nodeTip(i), e); });
      gg.on('mouseleave', hideTooltip);
      gg.on('click', function () { selectIndex(i); nodePopup(i); });

      // index numeral above the circle, nudged toward the incoming edge (as in the source)
      var off = 0;
      if (i > 1) off = (POS[i >> 1][0] > x) ? 12 : -12;
      halo(gLabels.text(String(i)).font({ family: SERIF, size: 21, anchor: 'middle' }).fill('#000')
        .center(x + off, y - R - 14));
      nodes[i] = { circle: circ, text: tv };
    })(i);
  }

  // ---------- array cells ----------
  var cells = {};
  for (var k = 1; k <= N; k++) {
    (function (k) {
      var gx = X0 + CW * (k - 1);
      var gg = gCells.group();
      var rct = gg.rect(CW, CH).move(gx, ATOP).fill(GRAY).stroke({ color: '#000', width: 1.8 });
      rct.css({ transition: 'fill .18s' });
      var tv = gg.text(String(A[k])).font({ family: SERIF, size: 26, anchor: 'middle' }).fill('#000');
      tv.center(gx + CW / 2, ATOP + CH / 2);
      gg.css('cursor', 'pointer');
      gg.on('mousemove', function (e) { showTooltip(nodeTip(k), e); });
      gg.on('mouseleave', hideTooltip);
      gg.on('click', function () { selectIndex(k); nodePopup(k); });
      halo(gLabels.text(String(k)).font({ family: SERIF, size: 21, anchor: 'middle' }).fill('#000')
        .center(cx(k), 172));
      cells[k] = { rect: rct, text: tv };
    })(k);
  }

  // ---------- comparison badges (only for highlighted links) ----------
  var badges = {};
  for (var c3 = 2; c3 <= N; c3++) {
    (function (c) {
      var p = c >> 1;
      var txt = A[p] + ' \u2265 ' + A[c];
      var mx = (POS[p][0] + POS[c][0]) / 2, my = (POS[p][1] + POS[c][1]) / 2;
      var perp = (POS[c][0] > POS[p][0]) ? 26 : -26;
      var t1 = gBadges.text(txt).font({ family: SANS, size: 17, anchor: 'middle' }).fill(CHID);
      halo(t1, 4.4); t1.center(mx + perp, my - 6);
      var g = arcGeom(p, c);
      var ax = (g.x1 + g.x2) / 2, ay = g.above ? g.y - g.h - 11 : g.y + g.h + 11;
      var t2 = gBadges.text(txt).font({ family: SANS, size: 16, anchor: 'middle' }).fill(CHID);
      halo(t2, 4.4); t2.center(ax, ay);
      t1.css('display', 'none'); t2.css('display', 'none');
      badges[c] = [t1, t2];
    })(c3);
  }

  // ---------- panel captions ----------
  gCaps.text('(a)').font({ family: SERIF, size: 28, anchor: 'middle' }).fill('#000').center(285, 404);
  gCaps.text('(b)').font({ family: SERIF, size: 28, anchor: 'middle' }).fill('#000').center(850, 404);

  // ---------- readout (hidden until the student interacts) ----------
  gReadout.rect(500, 142).move(600, 4).fill('#fcfcfd').stroke({ color: '#c9ced4', width: 1.2 }).radius(5);
  var RO = [];
  for (var q = 0; q < 4; q++) {
    RO.push(gReadout.text('').font({ family: SANS, size: 19, anchor: 'start' }).fill('#222')
      .amove(614, 14 + q * 26));
  }
  var ROsize = gReadout.text('A.length = A.heap-size = 10')
    .font({ family: SERIF, size: 19, anchor: 'start', style: 'italic' }).fill('#444').amove(614, 120);
  gReadout.css('display', 'none');

  // ---------- state & render ----------
  var state = { i: 1, mode: 'Structural links', active: false };

  function hideAllBadges() {
    for (var c = 2; c <= N; c++) { badges[c][0].css('display', 'none'); badges[c][1].css('display', 'none'); }
  }

  function render() {
    var i = state.i, p = i >> 1, l = 2 * i, r = 2 * i + 1;
    var k, c;

    if (!state.active) {
      for (k = 1; k <= N; k++) { nodes[k].circle.fill(GRAY); cells[k].rect.fill(GRAY); }
      for (c = 2; c <= N; c++) {
        edges[c].stroke({ color: '#000', width: 1.8 }).opacity(1);
        arcs[c].stroke({ color: '#000', width: 1.3 }).opacity(1);
      }
      hideAllBadges();
      gReadout.css('display', 'none');
      return;
    }

    var role = {};
    if (p >= 1) role[p] = 'par';
    if (l <= N) role[l] = 'chi';
    if (r <= N) role[r] = 'chi';
    role[i] = 'sel';

    for (k = 1; k <= N; k++) {
      var f = role[k] === 'sel' ? SEL : role[k] === 'par' ? PAR : role[k] === 'chi' ? CHI : GRAY;
      nodes[k].circle.fill(f);
      cells[k].rect.fill(f);
    }

    var showProp = (state.mode !== 'Structural links');
    var dim = (state.mode === 'Heap property');
    hideAllBadges();

    for (c = 2; c <= N; c++) {
      var pp = c >> 1, rl = 'none';
      if (c === i && pp >= 1) rl = 'par';
      else if (pp === i) rl = 'chi';
      var col = rl === 'par' ? PARD : rl === 'chi' ? CHID : '#000';
      var op = rl === 'none' ? (dim ? 0.15 : 1) : 1;
      edges[c].stroke({ color: col, width: rl === 'none' ? 1.8 : 4 }).opacity(op);
      arcs[c].stroke({ color: col, width: rl === 'none' ? 1.3 : 3.2 }).opacity(op);
      if (showProp && rl !== 'none') {
        badges[c][0].fill(rl === 'par' ? PARD : CHID).css('display', '');
        badges[c][1].fill(rl === 'par' ? PARD : CHID).css('display', '');
      }
    }

    gReadout.css('display', '');
    RO[0].text('i = ' + i + '      A[i] = ' + A[i]).fill(SELD);
    if (p >= 1) RO[1].text('PARENT(i) = \u230Ai/2\u230B = ' + p + '   \u2192   A[' + p + '] = ' + A[p]).fill(PARD);
    else RO[1].text('PARENT(i) = \u230A1/2\u230B = 0   \u2192   none (root)').fill('#8a9096');
    if (l <= N) RO[2].text('LEFT(i) = 2i = ' + l + '   \u2192   A[' + l + '] = ' + A[l]).fill(CHID);
    else RO[2].text('LEFT(i) = 2i = ' + l + '   \u2192   none ( > heap-size 10 )').fill('#8a9096');
    if (r <= N) RO[3].text('RIGHT(i) = 2i+1 = ' + r + '   \u2192   A[' + r + '] = ' + A[r]).fill(CHID);
    else RO[3].text('RIGHT(i) = 2i+1 = ' + r + '   \u2192   none ( > heap-size 10 )').fill('#8a9096');
    ROsize.text('A.length = A.heap-size = 10');
  }

  function apply(i, mode, active) {
    state.i = Math.max(1, Math.min(N, i | 0));
    state.mode = mode;
    state.active = !!active;
    render();
  }

  // ---------- control handlers ----------
  window.update_indexSlider = function (v) { apply(v, state.mode, true); };
  window.toggle_overlayMode = function (m) { apply(state.i, m, true); };
  window.trigger_clearSel = function () { apply(state.i, state.mode, false); };

  function syncInputs(i, mode) {
    var s = document.getElementById('indexSliderInput');
    var o = document.getElementById('indexSliderVal');
    var sel = document.getElementById('overlayModeInput');
    if (s) s.value = i;
    if (o) o.value = i;
    if (sel && mode) sel.value = mode;
  }

  function selectIndex(i) {
    syncInputs(i, state.mode);
    apply(i, state.mode, true);
  }
  window.selectHeapIndex = selectIndex;

  // ---------- demo steps ----------
  var steps = [
    { title: 'Two pictures, one heap', narration: 'Left: a nearly-complete binary tree. Right: a flat array. Read the tree level by level, left to right, and you get exactly the array: 16, 14, 10, 8, 7, 9, 3, 2, 4, 1. The arcs show the tree edges hiding inside the row.', state: { i: 1, mode: 'Structural links' } },
    { title: 'The root and its children', narration: 'With i = 1 the children sit at 2i = 2 and 2i + 1 = 3 \u2014 cells 14 and 10, exactly the root\u2019s two tree children. There is no parent, because \u230A1/2\u230B = 0 falls outside the array.', state: { i: 1, mode: 'Structural links' } },
    { title: 'Climbing up: parent = \u230Ai/2\u230B', narration: 'At i = 5 the parent index is \u230A5/2\u230B = 2, and the node holding 7 does hang below the node holding 14. Indices 4 and 5 both map back to parent 2 \u2014 integer division folds two children into one parent.', state: { i: 5, mode: 'Structural links' } },
    { title: 'Where the tree runs out', narration: 'Node 5 would have children 10 and 11, but the heap size is 10, so it keeps only a left child. At i = 6 both child indices already exceed the array \u2014 that is precisely what makes a node a leaf.', state: { i: 6, mode: 'Structural links' } },
    { title: 'The max-heap property', narration: 'Now the value order: every parent\u2013child link carries A[parent] \u2265 A[child]. Here 14 \u2265 8, 8 \u2265 2 and 8 \u2265 4. The largest element must sit at the root \u2014 yet the two siblings A[8] = 2 and A[9] = 4 are in no particular order.', state: { i: 4, mode: 'Heap property' } },
    { title: 'Layout and order together', narration: 'Both overlays at once separate the two ideas: index arithmetic decides who is whose child, and the heap property constrains values only along those parent\u2013child links \u2014 never left to right across the array.', state: { i: 2, mode: 'Both' } }
  ];
  var cur = 0;

  function setStep(k) {
    cur = (k + steps.length) % steps.length;
    var st = steps[cur];
    syncInputs(st.state.i, st.state.mode);
    apply(st.state.i, st.state.mode, cur !== 0);
    var nar = document.getElementById('demoNarration');
    if (nar) nar.innerHTML = '<b>' + st.title + '</b><br>' + st.narration;
    var lab = document.getElementById('stepLabel');
    if (lab) lab.textContent = 'Step ' + (cur + 1) + ' / ' + steps.length;
  }
  window.nextStep = function () { setStep(cur + 1); };
  window.prevStep = function () { setStep(cur - 1); };

  setStep(0);
  window.__markRendered();
})();
// @FIGURE_CODE_END

